def check_girth(n, edges):
    import collections
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        # BFS to find shortest cycle
        dist = {i: 0}
        parent = {i: -1}
        queue = collections.deque([i])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Cycle found
                    if dist[u] + dist[v] + 1 < 8:
                        return False, dist[u] + dist[v] + 1
    return True, None

